CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL,
 password_hash text NOT NULL, role text NOT NULL DEFAULT 'participant' CHECK(role IN ('participant','ops','reviewer','finance','superadmin')),
 email_verified_at timestamptz, disabled_at timestamptz, totp_secret text, totp_confirmed boolean NOT NULL DEFAULT false,
 totp_last_step bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_tokens (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('verify','reset')), expires_at timestamptz NOT NULL);
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE social_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), platform text NOT NULL CHECK(platform IN ('tiktok','instagram')), handle text NOT NULL, UNIQUE(user_id,platform,handle));
CREATE TABLE payment_destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), bank_code text NOT NULL, account_cipher text NOT NULL, account_last4 text NOT NULL, holder text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE films (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, studio text NOT NULL, genre text NOT NULL, release_date date);
CREATE TABLE campaigns (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), film_id uuid NOT NULL REFERENCES films(id), slug text NOT NULL UNIQUE,
 title text NOT NULL, brief text NOT NULL, phase text NOT NULL, platforms text[] NOT NULL,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','paused','measuring','closed')),
 quota integer NOT NULL CHECK(quota BETWEEN 1 AND 100000), budget bigint NOT NULL CHECK(budget>0 AND budget<=1000000000000),
 reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0), spent bigint NOT NULL DEFAULT 0 CHECK(spent>=0),
 upload_deadline timestamptz NOT NULL, cutoff_at timestamptz NOT NULL, color text NOT NULL DEFAULT '#503256',
 current_rule_id uuid, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(cutoff_at>=upload_deadline), CHECK(reserved+spent<=budget)
);
CREATE TABLE campaign_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id), version integer NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,version));
ALTER TABLE campaigns ADD CONSTRAINT current_rule_fk FOREIGN KEY(current_rule_id) REFERENCES campaign_rules(id);
CREATE TABLE campaign_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id), version integer NOT NULL DEFAULT 1, name text NOT NULL, storage_key text NOT NULL UNIQUE, mime text NOT NULL, size integer NOT NULL, embargo_at timestamptz NOT NULL, rights_note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE participations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id), user_id uuid NOT NULL REFERENCES users(id), rule_id uuid NOT NULL REFERENCES campaign_rules(id), platform text NOT NULL CHECK(platform IN ('tiktok','instagram')), status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','submitted','approved','rejected','expired','settled')), reserve_amount bigint NOT NULL CHECK(reserve_amount>0), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,user_id));
CREATE INDEX participations_campaign ON participations(campaign_id,status);
CREATE TABLE submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participation_id uuid NOT NULL UNIQUE REFERENCES participations(id), user_id uuid NOT NULL REFERENCES users(id), campaign_id uuid NOT NULL REFERENCES campaigns(id), platform text NOT NULL, post_key text NOT NULL UNIQUE, url text NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','revision','approved','rejected','settled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submission_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), url text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), user_id uuid NOT NULL REFERENCES users(id), storage_key text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, size integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), reviewer_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK(decision IN ('approved','revision','rejected')), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE view_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), reported_by uuid NOT NULL REFERENCES users(id), views bigint NOT NULL CHECK(views>=0 AND views<=100000000000), captured_at timestamptz NOT NULL, evidence_id uuid NOT NULL REFERENCES evidence_files(id), status text NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','accepted','rejected')), accepted_by uuid REFERENCES users(id), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id), snapshot_id uuid REFERENCES view_snapshots(id), reviewer_id uuid NOT NULL REFERENCES users(id), accepted_views bigint NOT NULL, amount bigint NOT NULL CHECK(amount>=0), status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','settled','void')), objection_until timestamptz NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX assessment_active ON assessments(submission_id) WHERE status <> 'void';
CREATE TABLE disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL UNIQUE REFERENCES assessments(id), user_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','upheld','revised')), resolution text, resolved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL UNIQUE REFERENCES submissions(id), assessment_id uuid NOT NULL UNIQUE REFERENCES assessments(id), user_id uuid NOT NULL REFERENCES users(id), amount bigint NOT NULL CHECK(amount>=0), release_at timestamptz NOT NULL, released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets (user_id uuid PRIMARY KEY REFERENCES users(id), pending bigint NOT NULL DEFAULT 0 CHECK(pending>=0), available bigint NOT NULL DEFAULT 0 CHECK(available>=0), held bigint NOT NULL DEFAULT 0 CHECK(held>=0), paid bigint NOT NULL DEFAULT 0 CHECK(paid>=0));
CREATE TABLE journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, reference_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES journal_entries(id), bucket text NOT NULL CHECK(bucket IN ('pending','available','held','paid','campaign')), delta bigint NOT NULL);
CREATE TABLE payout_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), destination_id uuid NOT NULL REFERENCES payment_destinations(id), destination_snapshot jsonb NOT NULL, amount bigint NOT NULL CHECK(amount>0), status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','sending','pending','succeeded','failed','cancelled','needs_review')), request_key text NOT NULL UNIQUE, provider_id text UNIQUE, provider_key text NOT NULL UNIQUE, failure_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX payout_one_active ON payout_requests(user_id) WHERE status IN ('requested','approved','sending','pending','needs_review');
CREATE TABLE payout_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), approved_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payout_batch_items (payout_id uuid PRIMARY KEY REFERENCES payout_requests(id), batch_id uuid NOT NULL REFERENCES payout_batches(id));
CREATE TABLE payout_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payout_id uuid NOT NULL REFERENCES payout_requests(id), status text NOT NULL, http_status integer, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint text NOT NULL UNIQUE, provider_id text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'received', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payout_id uuid REFERENCES payout_requests(id), provider_id text NOT NULL, reason text NOT NULL, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, object_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox(status,available_at);
